// Des: Send one owner-captured request with a hard deadline
// Flo: host guard > any method with headers and body > no redirects > capped body inflate > worker thread with deadline, abandoned worker frees itself
// I/O: Spec (url, method, headers, body) + caps (caller) > Resp (code, content type, body copy); errors BlockedHost TooBig Timeout BadStatus
// ===================================================================
const std = @import("std"); const http = std.http; const flate = std.compress.flate; const safe = @import("nt-safe-guar.zig"); const urln = @import("ut-urlz-norm.zig"); const spec = @import("pa-spec-read.zig"); const cdp = @import("nt-brow-cdpz.zig");
const CF = .{ .redb = 4096, .trnb = 8192, .tick = 10 };
pub const Opts = struct { time_mill: u32 = 30000, body_maxz: usize = 5242880, priv: bool = false };
pub const Resp = struct { code: u16, ctyp: []const u8, body: []const u8 };
const Job = struct { gpaz: std.mem.Allocator, iozz: std.Io, meth: []u8, urlz: []u8, body: []u8, heds: []http.Header, hbuf: [][]u8, opts: Opts, done: std.atomic.Value(bool) = .init(false), refs: std.atomic.Value(u32) = .init(2), code: u16 = 0, ctyp: []u8 = &.{}, rbody: []u8 = &.{}, errn: ?anyerror = null,
fn rel(self: *Job) void { if (self.refs.fetchSub(1, .acq_rel) != 1) return; const gpaz = self.gpaz; gpaz.free(self.meth); gpaz.free(self.urlz); gpaz.free(self.body); for (self.hbuf) |hb| gpaz.free(hb); gpaz.free(self.hbuf); gpaz.free(self.heds); gpaz.free(self.ctyp); gpaz.free(self.rbody); gpaz.destroy(self); } };
fn run(job: *Job) !void { const gpaz = job.gpaz; const part = try urln.urlSplit(job.urlz); try safe.hostChek(job.iozz, part.host, job.opts.priv); const uri = std.Uri.parse(job.urlz) catch return error.BadUrl; const mthd = std.meta.stringToEnum(http.Method, job.meth) orelse return error.BadSpec; var clnt: http.Client = .{ .allocator = gpaz, .io = job.iozz }; defer clnt.deinit(); var req = try clnt.request(mthd, uri, .{ .keep_alive = false, .redirect_behavior = .unhandled, .extra_headers = job.heds }); defer req.deinit(); if (job.body.len > 0) { req.transfer_encoding = .{ .content_length = job.body.len }; try req.sendBodyComplete(job.body); } else { try req.sendBodiless(); } var redb: [CF.redb]u8 = undefined; var resp = try req.receiveHead(&redb); job.code = @backingInt(resp.head.status); var ct: []const u8 = ""; var iter = resp.head.iterateHeaders(); while (iter.next()) |item| { if (std.ascii.eqlIgnoreCase(item.name, "content-type")) ct = item.value; } job.ctyp = try gpaz.dupe(u8, ct); const trnb = try gpaz.alloc(u8, CF.trnb); defer gpaz.free(trnb); const winb = try gpaz.alloc(u8, flate.max_window_len); defer gpaz.free(winb); var deco: http.Decompress = undefined; const rdrz = resp.readerDecompressing(trnb, &deco, winb); job.rbody = rdrz.allocRemaining(gpaz, .limited(job.opts.body_maxz)) catch |err| switch (err) { error.StreamTooLong => return error.TooBig, error.OutOfMemory => return error.OutOfMemory, error.ReadFailed => return resp.bodyErr() orelse error.ReadFailed }; }
fn work(job: *Job) void { run(job) catch |err| { job.errn = err; }; job.done.store(true, .release); job.rel(); }
pub fn specFetc(gpaz: std.mem.Allocator, aren: std.mem.Allocator, iozz: std.Io, spc: spec.Spec, opts: Opts) !Resp { const job = try gpaz.create(Job); const meth = try gpaz.dupe(u8, spc.meth); const urlz = try gpaz.dupe(u8, spc.urlz); const body = try gpaz.dupe(u8, spc.body); const heds = try gpaz.alloc(http.Header, spc.hdrs.len); const hbuf = try gpaz.alloc([]u8, spc.hdrs.len * 2); for (spc.hdrs, 0..) |item, ix| { hbuf[ix * 2] = try gpaz.dupe(u8, item.name); hbuf[ix * 2 + 1] = try gpaz.dupe(u8, item.valu); heds[ix] = .{ .name = hbuf[ix * 2], .value = hbuf[ix * 2 + 1] }; } job.* = .{ .gpaz = gpaz, .iozz = iozz, .meth = meth, .urlz = urlz, .body = body, .heds = heds, .hbuf = hbuf, .opts = opts }; const thr = std.Thread.spawn(.{}, work, .{job}) catch { job.rel(); job.rel(); return error.Unexpected; }; thr.detach(); const dead = cdp.nowMs(iozz) + opts.time_mill; while (!job.done.load(.acquire)) { if (cdp.nowMs(iozz) > dead) { job.rel(); return error.Timeout; } std.Io.sleep(iozz, .fromMilliseconds(CF.tick), .awake) catch {}; } defer job.rel(); if (job.errn) |err| return err; return .{ .code = job.code, .ctyp = try aren.dupe(u8, job.ctyp), .body = try aren.dupe(u8, job.rbody) }; }
